vec4 plane = texture(sampler_fc_plane, multiply(uv_adj-0.5, rot) * 4.0 + 0.5);
//perlin noise
vec3 final_noise = vec3( 0.0 , 0.0 , 0.0 );
vec3 uvx = vec3(uv.x + q7, uv.y + q8, 2.0 + q1);
for(int i=0;i<4;i++)
final_noise +=(1.0/pow( 2.0 ,i))*(tex3D(sampler_noisevol_hq, uvx*pow( 2.0 ,i)) * 2.0-1);
// Remove the sign from the noise and prep
