ret = vec3(ret.x,ret.y,0.8 + 0.05*ret.x);
//fly throught the clouds
vec3 plane_cloud =  (ret.x  > 0.3 ? ret  :  0)*(plane.w * 2.0 - plane.w)*0.5;
ret = texture(sampler_main, uv) + ret*(1.0 - plane.w) +  plane_cloud   + plane*plane.w;
}

